    "vcsPermalink": "https://github.com/calcom/cal.com/blob/180ede28f0bddf2738933a6e60a8e80f6116d7da/packages/app-store/salesforce/sfdc-package/force-app/main/default/classes/UserUpdateHandlerTest.cls#L54-L87",
